+            return new HashAggregationOperator(
+                aggregators,
+                () -> BlockHash.build(hashGroups, driverContext.blockFactory(), maxPageSize, false),
+                driverContext
+            );
+        }
+
+        @Override
+        public String describe() {
+            return "TimeSeriesIntermediateAggregationOperatorFactory";
+        }
+    }
+
+    public record Final(
