+        List<AggregatorFunctionSupplier> outerRates,
+        List<AggregatorFunctionSupplier> nonRates,
+        int maxPageSize
+    ) implements Operator.OperatorFactory {
+        @Override
+        public Operator get(DriverContext driverContext) {
